import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { buildFeed, tsvChunks } from './candidate/src/generator.js';
import { config as baseConfig, market as baseMarket, now, product, variant, snapshot } from './candidate/test/fixtures.js';
globalThis.fetch=()=>{throw new Error('network_prohibited');};
const hash=s=>createHash('sha256').update(s).digest('hex');
const holds=JSON.parse(await fs.readFile('./candidate/test/holds.fixture.json','utf8'));
const cases=[];
function fixture(country,products){
 const currency=country==='CA'?'CAD':'GBP';
 const market={...structuredClone(baseMarket),country,currency,key:country.toLowerCase()+'-en',
  landingQuery:{country,currency},marketId:'gid://shopify/Market/99001',
  expectedCatalogs:[{id:'gid://shopify/MarketCatalog/99002',publicationId:'gid://shopify/Publication/99003'}],
  shippingCostOnly:{country,currency,amount:'0.00',verified:true,evidenceSha256:hash('INDEPENDENT_SYNTHETIC_ONLY')}};
 const config=structuredClone(baseConfig);config.returnPolicy.emitLabels=false;config.eligibilityHolds=structuredClone(holds);config.markets=[market];
 products??=[product(1,[variant(101,currency)])];products.forEach(p=>{p.catalogPublished=true;});
 const source=snapshot(products,market);source.marketContext={currency,catalogs:structuredClone(market.expectedCatalogs),activeMarketIds:[market.marketId]};source.finalMarketContext=structuredClone(source.marketContext);
 return {source,config,market};
}
for(const country of ['CA','GB']){
 let f=fixture(country,[]),r=await buildFeed(f.source,f.config,f.market,{now,previousIds:['old-synthetic-offer']});
 let s=await buildFeed(f.source,f.config,f.market,{now,materialize:false});
 assert.equal(r.ok,true);assert.equal(r.rows.length,0);assert.deepEqual(r.diagnostics.lifecycle.removed,['old-synthetic-offer']);
 assert.equal(s.columns.filter(x=>x==='shipping').length,1);assert.equal(r.tsv,s.columns.join('\t')+'\n');
 assert.equal(Buffer.concat([...tsvChunks(s.rows,s.columns)]).toString(),r.tsv);
 cases.push({name:country+' empty complete source retains exact single shipping header and lifecycle',pass:true});
 f=fixture(country);Object.assign(f.source.products[0],{shipping:'UNTRUSTED',max_handling_time:1,max_transit_time:1,returns:'UNTRUSTED',return_policy_label:'UNTRUSTED'});
 Object.assign(f.source.products[0].variants[0],{shipping:'UNTRUSTED',max_handling_time:1,max_transit_time:1,returns:'UNTRUSTED',return_policy_label:'UNTRUSTED'});
 r=await buildFeed(f.source,f.config,f.market,{now});assert.equal(r.ok,true);
 assert.equal(r.rows[0].shipping,country+':::0.00 '+f.market.currency);assert.ok(!r.tsv.includes('UNTRUSTED'));
 const header=r.tsv.split('\n')[0].split('\t');assert.ok(!header.some(x=>/handling|transit|return/.test(x)));assert.equal(header.filter(x=>x==='shipping').length,1);
 cases.push({name:country+' unused source timing and return properties cannot leak into TSV',pass:true});
 f=fixture(country);f.market.landingQuery.variant='999';
 r=await buildFeed(f.source,f.config,f.market,{now});assert.equal(r.ok,false);assert.equal(r.tsv,null);assert.deepEqual(r.rows,[]);
 assert.ok(r.diagnostics.errors.some(x=>x.code==='unsupported_landing_query'));
 cases.push({name:country+' reserved variant query override fails without a partial feed',pass:true});
}
process.stdout.write(JSON.stringify({scope:'Synthetic in-memory only; no network or generated files',cases,pass:cases.length,fail:0})+'\n');
